## Gives a stereophonic range to an additive synthesis note. while very close by, each partial has#a spatial x-axis deviation from the fundamental.from random import gaussdef paneos_espectrales(panoramica_gral, espectro_dist):		espacializacion 	= [panoramica_gral]	contador		= len(espectro_dist) - 1		while contador > 0:		un_paneo = gauss(panoramica_gral, .01)		if 0 < un_paneo < 1:			espacializacion.append(un_paneo)			contador = contador -1	return espacializacion